    weight = weight.reshape([-1])
    if not assume_sorted:
        sortidx = torch.argsort(x)
        x, weight = x[sortidx], weight[torch.remainder(sortidx, len(weight))]

    acc_w = torch.cumsum(weight, dim=0)
